vec3 uColor = vec3(0.0, 1.0, 0.0);


void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Screen resolution and normalized coordinates
    vec2 resolution = iResolution.xy;
    vec2 uv = fragCoord.xy / resolution;

    // Button size (normalized)
    vec2 buttonSize = vec2(0.025, 0.05); // 10% of screen width and height

    // Button positions
    vec2 blueButtonPos = vec2(1.0 - buttonSize.x, 0.0);       // Bottom-right corner
    vec2 yellowButtonPos = vec2(1.0 - 2.0 * buttonSize.x, 0.0); // To the left of the blue button

    // Default background color: red
    vec4 bgColor = vec4(1.0, 0.0, 0.0, 1.0); // Red

    // Draw the blue button
    if (uv.x > blueButtonPos.x && uv.x < blueButtonPos.x + buttonSize.x &&
        uv.y > blueButtonPos.y && uv.y < blueButtonPos.y + buttonSize.y) {
        // Draw blue button
        fragColor = vec4(0.0, 0.0, 1.0, 1.0);

        // Draw '+' symbol on the blue button
        vec2 localUV = (uv - blueButtonPos) / buttonSize; // Normalize UV to button space
        if (abs(localUV.x - 0.5) < 0.02 && localUV.y > 0.25 && localUV.y < 0.75) {
            fragColor = vec4(1.0, 1.0, 1.0, 1.0); // White for '+'
        }       
        if (abs(localUV.y - 0.5) < 0.02 && localUV.x > 0.25 && localUV.x < 0.75) {
            fragColor = vec4(1.0, 1.0, 1.0, 1.0); // White for horizontal bar of '+'
        }
        return;
    }

    // Draw the yellow button
    if (uv.x > yellowButtonPos.x && uv.x < yellowButtonPos.x + buttonSize.x &&
        uv.y > yellowButtonPos.y && uv.y < yellowButtonPos.y + buttonSize.y) {
        // Draw yellow button
        fragColor = vec4(1.0, 1.0, 0.0, 1.0);

        // Draw '-' symbol on the yellow button
        vec2 localUV = (uv - yellowButtonPos) / buttonSize; // Normalize UV to button space
        if (abs(localUV.y - 0.5) < 0.02 && localUV.x > 0.25 && localUV.x < 0.75) {
            fragColor = vec4(0.0, 0.0, 0.0, 1.0); // Black for '-'
        }
        return;
    }

    // read center and size from buffer A
    vec2 center = texture(iChannel0, vec2(1.0)).xy;
    float uSize = texture(iChannel0, vec2(1.0)).z;

    // Compute Mandelbrot set for that pixel
    vec2 coord = vec2(uv.x-0.5, (uv.y-0.5)*iResolution.y/iResolution.x);
    const int maxIter = 30;
    float x = center.x + uSize * coord.x;
    float y = center.y + uSize * coord.y;
    float za = 0.0;
    float zb = 0.0;
    int iter = 0;

    while (iter<maxIter && za*za+zb*zb<9.0) {
        float a = za;
        float b = zb;
        za = a*a-b*b + x;
        zb = 2.0*a*b + y;
        iter = iter + 1;
    }
    if (za*za+zb*zb<9.0)
        fragColor = vec4(1.0, 1.0, 1.0, 1.0);
    else {
        vec3 color = uColor * (1.0-float(iter)/float(maxIter));
        fragColor = vec4(color, 1.0);
    }
}

float uSize = 5.0;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Read center and size
    vec2 center = texture(iChannel0, vec2(1.0)).xy;
    float size = texture(iChannel0, vec2(1.0)).z;

    // Read the mouse previous state from iChannel0
    vec4 prevMouseState = texture(iChannel0, vec2(0.0)); 
    vec2 prevMouse = prevMouseState.rg; // Previous mouse position (x, y)
    float initialMouse = prevMouseState.b; // Initial mouse down position (x, y)

    // in the initial frame, set initial values 
    if (iFrame == 0) {
        center = vec2(0.0);
        size = uSize;
        prevMouse = vec2(0.0);
        initialMouse = 0.0; //0:mouseup; 1:mousedown; 2:mousemove
    }

    // Check if the mouse is pressed
    bool isMousePressed = (iMouse.z > 0.0); // iMouse.z > 0 means left button is pressed

    // Screen resolution and normalized coordinates
    vec2 resolution = iResolution.xy;
    vec2 uv = fragCoord.xy / resolution;

    // Button size (normalized)
    vec2 buttonSize = vec2(0.025, 0.05); // 10% of screen width and height

    // Button positions
    vec2 blueButtonPos = vec2(1.0 - buttonSize.x, 0.0);       // Bottom-right corner
    vec2 yellowButtonPos = vec2(1.0 - 2.0 * buttonSize.x, 0.0); // To the left of the blue button

    // Detect if the mouse is over the blue button
    bool isMouseOverBlue = false;
    if (isMousePressed) {
        vec2 mouseUV = iMouse.xy / resolution;
        isMouseOverBlue = mouseUV.x > blueButtonPos.x && mouseUV.x < blueButtonPos.x + buttonSize.x &&
                          mouseUV.y > blueButtonPos.y && mouseUV.y < blueButtonPos.y + buttonSize.y;
    }

    // Detect if the mouse is over the yellow button
    bool isMouseOverYellow = false;
    if (isMousePressed) {
        vec2 mouseUV = iMouse.xy / resolution;
        isMouseOverYellow = mouseUV.x > yellowButtonPos.x && mouseUV.x < yellowButtonPos.x + buttonSize.x &&
                            mouseUV.y > yellowButtonPos.y && mouseUV.y < yellowButtonPos.y + buttonSize.y;
    }

    // Change background color based on which button is pressed
    if (isMouseOverBlue) {
        size = size * 0.99; // zoom in
    } else if (isMouseOverYellow) {
        size = size / 0.99; // zoom out
    } else if (iMouse.z > 0.0) { // check if drawing
        vec2 mousePos = iMouse.xy / iResolution.xy;
        if (initialMouse > 0.5) {
            vec2 scaleFactor = vec2(1.0,iResolution.y/iResolution.x);
            center = center - size*scaleFactor*(mousePos-prevMouse);
        }
        prevMouse = mousePos;
        initialMouse = 1.0;
    } else
        initialMouse = 0.0;

    if (fragCoord.x > 0.5)
        fragColor = vec4(center,size,1.0);
    else
        fragColor = vec4(prevMouse, initialMouse, 1.0);
}
